function ProfilePage({session,onLogout,onSessionUpdate}:{session:Profile;onLogout:()=>void;onSessionUpdate:(p:Profile)=>void}){
 const sector=sectors.find(s=>s.id===session.sector_id); const [busy,setBusy]=useState(false); const [error,setError]=useState(''); const inputRef=useRef<HTMLInputElement|null>(null);
 async function uploadAvatar(file:File){
  if(!file.type.startsWith('image/')){setError('اختر صورة فقط.');return}
  if(file.size>5*1024*1024){setError('حجم الصورة يجب ألا يتجاوز 5 ميجابايت.');return}
  setBusy(true);setError('');
  try{
   const token=localStorage.getItem('ss_access_token')||''; const path=`${session.id}/avatar`;
   const res=await fetch(`${ENV_URL}/storage/v1/object/avatars/${encodeURIComponent(session.id)}/avatar`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type,'x-upsert':'true'},body:file});
   const raw=await res.text(); let d:any={}; try{d=raw?JSON.parse(raw):{}}catch{} if(!res.ok)throw new Error(d?.message||d?.error||raw||'فشل رفع الصورة');
   const url=`${ENV_URL}/storage/v1/object/public/avatars/${encodeURIComponent(session.id)}/avatar?v=${Date.now()}`;
   const updated=await supabase(`profiles?id=eq.${encodeURIComponent(session.id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({avatar_url:url,avatar_path:path})});
   const next={...session,avatar_url:url,avatar_path:path}; onSessionUpdate((updated&&updated[0])?updated[0]:next);
  }catch(e:any){setError(e.message||'تعذر تغيير الصورة.')}finally{setBusy(false)}
 }
 async function removeAvatar(){
  if(!session.avatar_path)return; setBusy(true);setError(''); try{const token=localStorage.getItem('ss_access_token')||''; await fetch(`${ENV_URL}/storage/v1/object/avatars/${session.avatar_path.split('/').map(encodeURIComponent).join('/')}`,{method:'DELETE',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`}}); await supabase(`profiles?id=eq.${encodeURIComponent(session.id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({avatar_url:null,avatar_path:null})}); onSessionUpdate({...session,avatar_url:null,avatar_path:null});}catch(e:any){setError(e.message||'تعذر حذف الصورة.')}finally{setBusy(false)}}
 return <><PageTitle title="ملفي الشخصي" sub="بيانات حسابك وإعدادات الوصول"><button className="primary" onClick={onLogout}><LogOut/> تسجيل الخروج</button></PageTitle><section className="profile-page-card"><div className="profile-avatar-wrap"><div className="profile-avatar">{session.avatar_url?<img src={session.avatar_url} alt="صورة الحساب"/>:session.full_name.slice(0,1)}</div><div className="avatar-actions"><button className="secondary small-btn" type="button" onClick={()=>inputRef.current?.click()} disabled={busy}><ImagePlus size={15}/> {session.avatar_url?'تغيير الصورة':'إضافة صورة'}</button>{session.avatar_url&&<button className="ghost small-btn" type="button" onClick={removeAvatar} disabled={busy}><Trash2 size={15}/> حذف</button>}<input ref={inputRef} type="file" hidden accept="image/*" onChange={e=>{const f=e.target.files?.[0];if(f)uploadAvatar(f);e.currentTarget.value=''}}/></div>{error&&<small className="form-error">{error}</small>}</div><div className="profile-info"><h2>{session.full_name}</h2><p>{roleName[session.role]}{sector?' · '+sector.name:''}</p><div className="profile-grid"><span><b>اسم المستخدم</b>{session.username}</span><span><b>الهاتف</b>{session.phone||'—'}</span><span><b>النوع</b>{session.gender==='female'?'بنات / أنثى':session.gender==='male'?'بنين / ذكر':'غير محدد'}</span><span><b>الحالة</b>{session.active?'نشط':'موقوف'}</span></div></div></section></>}
