function SectorSecretaryDashboard({session,members,classes,setTab}:{session:Profile;members:Profile[];classes:ClassRoom[];setTab:(t:Tab)=>void}){return <><div className="dashboard-stats"><DashCard icon={GraduationCap} n={String(classes.length)} t="فصول القطاع" onClick={()=>setTab('sectors')}/><DashCard icon={Users} n={String(members.length)} t="مخدومو القطاع" onClick={()=>setTab('members')}/><DashCard icon={CalendarCheck} n="الحضور" t="متابعة حضور القطاع" onClick={()=>setTab('attendance')}/><DashCard icon={MessageCircle} n="شات" t="شات أمناء القطاعات" onClick={()=>setTab('chat')}/></div><RoleSection title="إدارة القطاع" sub="صلاحيات أمين القطاع تقتصر على قطاعه"><QuickRole title="الخدام والمخدومون" text="متابعة فريق الخدمة والمخدومين في قطاعك." icon={Users} onClick={()=>setTab('members')}/><QuickRole title="الحضور" text="متابعة الحضور والغياب وتقارير القطاع." icon={CalendarCheck} onClick={()=>setTab('attendance')}/><QuickRole title="المحتوى" text="متابعة محتوى القطاع وأنشطته." icon={BookOpen} onClick={()=>setTab('lessons')}/><QuickRole title="شات الإدارة" text="التواصل مع أب الكنيسة وأمين الخدمة وأمناء القطاعات." icon={MessageCircle} onClick={()=>setTab('staffchat')}/></RoleSection></>}

function ServantDashboard({session,members,classes,setTab}:{session:Profile;members:Profile[];classes:ClassRoom[];setTab:(t:Tab)=>void}){const sector=sectors.find(s=>s.id===session.sector_id);return <><div className="servant-dashboard-head"><div className="sector-identity"><span>{sector?.emoji||'🕊️'}</span><div><b>{sector?.name||'قطاعي'}</b><small>{sector?.subtitle||'خدمتك ومسؤولياتك'}</small></div></div></div><div className="dashboard-stats"><DashCard icon={Users} n={String(members.length)} t="مخدومي" onClick={()=>setTab('members')}/><DashCard icon={GraduationCap} n={String(classes.length)} t="فصولي" onClick={()=>setTab('sectors')}/><DashCard icon={CalendarCheck} n="الحضور" t="تسجيل حضور المخدومين" onClick={()=>setTab('attendance')}/><DashCard icon={MessageCircle} n="شات" t="شات القطاع" onClick={()=>setTab('chat')}/></div><RoleSection title="خدمتي" sub="الوظائف الأساسية التي تحتاجها في يوم الخدمة"><QuickRole title="مخدومي" text="متابعة بيانات مخدومي الفصول المسندة إليك." icon={Users} onClick={()=>setTab('members')}/><QuickRole title="الحضور" text="تسجيل ومراجعة حضور فصولك." icon={CalendarCheck} onClick={()=>setTab('attendance')}/><QuickRole title="المحتوى الروحي" text="دروس وتأملات خاصة بقطاعك وفصولك." icon={BookOpen} onClick={()=>setTab('lessons')}/><QuickRole title="الشات" text="التواصل الجماعي داخل قطاعك." icon={MessageCircle} onClick={()=>setTab('chat')}/><QuickRole title="أعياد الميلاد" text="متابعة أعياد ميلاد مخدوميك." icon={Cake} onClick={()=>setTab('birthdays')}/></RoleSection></>}
function MemberDashboard({session,members,setTab}:{session:Profile;members:Profile[];setTab:(t:Tab)=>void}){
 const sector=sectors.find(s=>s.id===session.sector_id);
 const [rows,setRows]=useState<Attendance[]>([]);
 useEffect(()=>{(async()=>{try{const a=await supabase(`attendance?select=id,class_id,member_id,date,present,attendance_type&member_id=eq.${encodeURIComponent(session.id)}&order=date.desc`);setRows(a||[])}catch{}})()},[session.id]);
 const service=rows.filter(r=>r.attendance_type==='service'); const mass=rows.filter(r=>r.attendance_type==='mass');
 const pct=(arr:Attendance[])=>arr.length?Math.round(arr.filter(r=>r.present).length/arr.length*100):0;
 const qr=`https://api.qrserver.com/v1/create-qr-code/?size=220x220&margin=10&data=${encodeURIComponent(`khidma-member:${session.id}`)}`;
 return <><div className="member-profile-card"><div className="member-avatar">{session.full_name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><span>مرحبًا بك</span><h2>{session.full_name}</h2><p>{sector?.name||'لم يتم تعيين قطاع بعد'} {session.class_id?' · فصل محدد':''}</p></div></div>
 <div className="member-attendance-mini"><div><b>{pct(service)}%</b><small>حضور الخدمة</small></div><div><b>{pct(mass)}%</b><small>حضور القداس</small></div><div className="member-qr-mini"><img src={qr} alt="QR"/><small>QR الحضور</small></div></div>
 <RoleSection title="مساحتي" sub="كل ما تحتاجه كمخدوم"><QuickRole title="شات القطاع" text="تواصل مع خدام ومخدومي قطاعك." icon={MessageCircle} onClick={()=>setTab('chat')}/><QuickRole title="المحتوى الروحي" text="الدروس والتأملات المتاحة لقطاعك." icon={BookOpen} onClick={()=>setTab('lessons')}/><QuickRole title="الأنشطة والخدمات" text="الإعلانات والفعاليات والصور والفيديوهات." icon={HeartHandshake} onClick={()=>setTab('services')}/></RoleSection><div className="member-verse">« دَعُوا الأَوْلَادَ يَأْتُونَ إِلَيَّ وَلاَ تَمْنَعُوهُمْ، لأَنَّ لِمِثْلِ هَؤُلاَءِ مَلَكُوتَ السَّمَاوَاتِ »<small>متى ١٩: ١٤</small></div></>}
function BirthdaysPage({session}:{session:Profile}){
 const [members,setMembers]=useState<Profile[]>([]); const [month,setMonth]=useState(new Date().getMonth()+1); const [loading,setLoading]=useState(true);
 useEffect(()=>{(async()=>{setLoading(true);try{const rows=await supabase('profiles?select=id,full_name,phone,birth_date,sector_id,class_id&role=eq.member&active=eq.true&order=full_name.asc');const scoped=(rows||[]).filter((p:Profile)=>isManager(session.role)?true:(p.sector_id===session.sector_id));setMembers(scoped)}catch{setMembers([])}finally{setLoading(false)}})()},[session.role,session.sector_id]);
 const birthdays=members.filter(m=>{if(!m.birth_date)return false;const d=new Date(m.birth_date+'T00:00:00');return d.getMonth()+1===month}).sort((a,b)=>{const da=new Date(a.birth_date!+'T00:00:00').getDate();const db=new Date(b.birth_date!+'T00:00:00').getDate();return da-db||a.full_name.localeCompare(b.full_name,'ar')});
 const today=new Date(); const todayList=birthdays.filter(m=>{const d=new Date(m.birth_date!+'T00:00:00');return d.getDate()===today.getDate()&&d.getMonth()+1===today.getMonth()+1});
 const months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];
 return <><PageTitle title="أعياد ميلاد المخدومين" sub={session.role==='servant'?'قائمة أعياد ميلاد مخدومي قطاعك.':'قائمة أعياد ميلاد المخدومين حسب الشهر.'}><div className="birthday-actions"><Cake/><span>{birthdays.length} عيد ميلاد</span></div></PageTitle><div className="birthday-toolbar"><label><span className="sr-only">الشهر</span><select value={month} onChange={e=>setMonth(Number(e.target.value))}>{months.map((m,i)=><option value={i+1} key={m}>{m}</option>)}</select></label>{todayList.length>0&&<div className="birthday-stat birthday-today"><Cake/><div><b>{todayList.length}</b><small>عيد ميلاد اليوم</small></div></div>}</div><div className="birthday-summary"><div className="birthday-stat"><Cake/><div><b>{birthdays.length}</b><small>أعياد ميلاد الشهر</small></div></div><div className="birthday-stat"><Users/><div><b>{members.filter(m=>m.birth_date).length}</b><small>مخدوم له تاريخ ميلاد</small></div></div><div className="birthday-stat"><CalendarDays/><div><b>{members.length}</b><small>إجمالي المخدومين</small></div></div></div>{loading?<div className="empty">جاري تحميل أعياد الميلاد...</div>:birthdays.length===0?<div className="birthday-empty"><Cake size={28}/><p>لا توجد بيانات أعياد ميلاد لهذا الشهر.</p></div>:<div className="birthday-list">{birthdays.map(m=>{const d=new Date(m.birth_date!+'T00:00:00');const sector=sectors.find(s=>s.id===m.sector_id);return <div className={'birthday-row '+(d.getDate()===today.getDate()&&d.getMonth()+1===today.getMonth()+1?'birthday-today':'')} key={m.id}><div className="birthday-day">{d.getDate()}</div><div className="birthday-info"><b>{m.full_name}</b><small>{sector?.name||'غير معين'} {m.phone?' · ':''}{m.phone&&<a className="birthday-phone" href={`tel:${m.phone}`}><Phone size={13}/>{m.phone}</a>}</small></div><div className="birthday-actions"><span>{d.getFullYear()}</span></div></div>})}</div>}</>}

function RoleSection({title,sub,children}:{title:string;sub:string;children:any}){return <section className="role-section"><div className="section-head"><div><h3>{title}</h3><p>{sub}</p></div></div><div className="role-quick-grid">{children}</div></section>}
function QuickRole({title,text,icon:Icon,onClick}:{title:string;text:string;icon:any;onClick:()=>void}){return <button className="quick-role" onClick={onClick}><span><Icon size={21}/></span><div><b>{title}</b><small>{text}</small></div><ChevronLeft size={16}/></button>}

function Stat({n,t}:{n:string;t:string}){return <div className="stat"><strong>{n}</strong><span>{t}</span><ArrowUpRight size={18}/></div>}
function SectorCard({sector,count,cls}:{sector:Sector;count:number;cls:number}){return <div className="sector-card"><span className="sector-emoji">{sector.emoji}</span><div><h4>{sector.name}</h4><p>{sector.subtitle}</p><small>{count} عضو · {cls} فصل</small></div><ChevronLeft/></div>}

function Sectors({session,selected,setSelected,setSelectedClass,goChat,goTab,refresh,refreshKey}:{session:Profile;selected:string;setSelected:(s:string)=>void;setSelectedClass:(s:string)=>void;goChat:()=>void;goTab:(t:Tab)=>void;refresh:()=>void;refreshKey:number}){
 const [classes,setClasses]=useState<ClassRoom[]>([]); const [members,setMembers]=useState<Profile[]>([]); const [servants,setServants]=useState<Profile[]>([]); const [modal,setModal]=useState(false); const [bulkModal,setBulkModal]=useState(false); const [assignModal,setAssignModal]=useState<ClassRoom|null>(null); const [name,setName]=useState(''); const [sector,setSector]=useState(session.sector_id&&YOUTH_DB_IDS.includes(session.sector_id)?'youth':(session.sector_id||'baby')); const [servant,setServant]=useState(''); const [newServant,setNewServant]=useState('');
 const allowedSectors=isManager(session.role)?sectors:sectors.filter(s=>sectorMatches(s.id,session.sector_id));
 useEffect(()=>{(async()=>{try{const [c,m,s]=await Promise.all([supabase('classes?select=id,sector_id,name,servant_id'),supabase('profiles?select=id,sector_id,role,full_name,class_id&active=eq.true'),supabase('profiles?select=id,full_name,role,sector_id&role=eq.servant&active=eq.true')]);
   const allClasses=c||[];
   const scopedClasses=session.role==='servant'?allClasses.filter((x:ClassRoom)=>sectorMatches(x.sector_id,session.sector_id)&&x.servant_id===session.id):allClasses.filter((x:ClassRoom)=>isManager(session.role)||sectorMatches(x.sector_id,session.sector_id));
   const ids=new Set(scopedClasses.map((x:ClassRoom)=>x.id));
   const allMembers=m||[];
   const scopedMembers=session.role==='servant'?allMembers.filter((x:Profile)=>x.role==='member'&&ids.has(x.class_id||'')):allMembers.filter((x:Profile)=>x.role==='member'&&(isManager(session.role)||sectorMatches(x.sector_id,session.sector_id)));
   setClasses(scopedClasses);setMembers(scopedMembers);setServants(s||[]);
 }catch(e){}})()},[refreshKey,session.id,session.role,session.sector_id]);
 useEffect(()=>{const first=allowedSectors[0]?.id;if(first&&!allowedSectors.some(s=>s.id===selected))setSelected(first)},[session.role,session.sector_id,selected]);
 async function add(e:FormEvent){e.preventDefault();if(!name.trim())return;try{const selectedServant=servants.find(x=>x.id===servant);const targetSector=sector;if(selectedServant&&!sectorMatches(selectedServant.sector_id,targetSector))throw new Error('لا يمكن تعيين خادم من قطاع مختلف لهذا الفصل.');await supabase('classes',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({name:name.trim(),sector_id:targetSector,servant_id:servant||null})});setName('');setServant('');setModal(false);refresh()}catch(err:any){alert(err.message)}}
 async function reassign(){if(!assignModal)return;try{const target=servants.find(x=>x.id===newServant);if(newServant && (!target || target.sector_id!==assignModal.sector_id))throw new Error('الخادم الجديد يجب أن يكون من نفس قطاع الفصل.');await supabase(`classes?id=eq.${encodeURIComponent(assignModal.id)}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({servant_id:newServant||null})});setAssignModal(null);setNewServant('');refresh()}catch(err:any){alert(err.message)}}
 const sectorClasses=(sid:string)=>classes.filter(c=>sectorDbIds(sid).includes(c.sector_id)); const sectorMembers=(sid:string)=>members.filter(m=>sectorDbIds(sid).includes(m.sector_id||'')); const sectorServants=(sid:string)=>servants.filter(v=>sectorDbIds(sid).includes(v.sector_id||''));
 return <><PageTitle title="القطاعات والفصول" sub="كل فصل يمكن إسناده لخادم من نفس القطاع، ويمكن تغيير الإسناد من قبل الإدارة">{isManager(session.role)&&<button className="primary" onClick={()=>setModal(true)}><Plus/>إنشاء فصل</button>}</PageTitle><div className="sector-list">{allowedSectors.map(s=><div className="sector-panel" key={s.id}><div className="sector-title"><span>{s.emoji}</span><div><h3>{s.name}</h3><p>{sectorMembers(s.id).length} عضو · {sectorClasses(s.id).length} فصل · {sectorServants(s.id).length} خادم</p></div><button className="chat-btn" onClick={()=>{setSelected(s.id);goChat()}}><MessageCircle/> شات القطاع</button></div><div className="sector-quick-actions"><button onClick={()=>{setSelected(s.id);goTab('members')}}><Users/> المخدومون</button><button onClick={()=>{setSelected(s.id);goTab('attendance')}}><CalendarCheck/> الحضور</button><button onClick={()=>{setSelected(s.id);goTab('lessons')}}><BookOpen/> المحتوى</button><button onClick={()=>{setSelected(s.id);goTab('services')}}><HeartHandshake/> الخدمات</button><button onClick={()=>{setSelected(s.id);goChat()}}><MessageCircle/> الشات</button></div><div className="class-grid">{sectorClasses(s.id).map(c=><button className="class-card class-card-open" key={c.id} onClick={()=>{setSelectedClass(c.id);goTab('class')}}><b>{c.name}</b><span>الخادم: {sectorServants(s.id).find(x=>x.id===c.servant_id)?.full_name||'غير معين'}</span><small>{members.filter(m=>m.class_id===c.id).length} مخدوم</small>{isManager(session.role)&&<span className="promote" onClick={(e)=>{e.stopPropagation();setAssignModal(c);setNewServant(c.servant_id||'')}}><ArrowRightLeft/> تغيير الخادم</span>}<span className="class-open-hint">فتح مساحة الفصل <ChevronLeft size={14}/></span></button>)}{isManager(session.role)&&<button className="add-class" onClick={()=>{setSector(s.id);setModal(true)}}><Plus/> فصل جديد</button>}</div></div>)}</div>{modal&&<Modal title="إنشاء فصل جديد" onClose={()=>setModal(false)}><form onSubmit={add}><label>القطاع<select value={sector} onChange={e=>{setSector(e.target.value);setServant('')}}>{allowedSectors.map(s=><option value={s.id} key={s.id}>{s.name}</option>)}</select></label><label>اسم الفصل<input value={name} onChange={e=>setName(e.target.value)} required placeholder="مثال: أصدقاء يسوع"/></label><label>الخادم المسؤول<select value={servant} onChange={e=>setServant(e.target.value)}><option value="">غير معين</option>{servants.filter(x=>sector==='youth'?YOUTH_DB_IDS.includes(x.sector_id||''):x.sector_id===sector).map(x=><option value={x.id} key={x.id}>{x.full_name}</option>)}</select></label><button className="primary full"><Save/>حفظ الفصل</button></form></Modal>}{assignModal&&<Modal title={`تغيير خادم فصل ${assignModal.name}`} onClose={()=>{setAssignModal(null);setNewServant('')}}><p className="modal-help">إذا كان الفصل مسندًا لخادم آخر، اختر الخادم الجديد من نفس القطاع. يمكن أيضًا اختيار «غير معين».</p><label>الخادم الجديد<select value={newServant} onChange={e=>setNewServant(e.target.value)}><option value="">غير معين</option>{servants.filter(x=>sectorMatches(x.sector_id,assignModal.sector_id)||(YOUTH_DB_IDS.includes(assignModal.sector_id)&&YOUTH_DB_IDS.includes(x.sector_id||''))).map(x=><option value={x.id} key={x.id}>{x.full_name}</option>)}</select></label><button className="primary full" onClick={reassign}><ArrowRightLeft/> تأكيد تغيير الإسناد</button></Modal>}</>
}


function ClassWorkspace({session,classId,refreshKey,onBack}:{session:Profile;classId:string;refreshKey:number;onBack:()=>void}){
 const [room,setRoom]=useState<ClassRoom|null>(null); const [members,setMembers]=useState<Profile[]>([]);
 const [tab,setTab]=useState<'overview'|'members'|'attendance'|'content'|'chat'|'visits'|'reports'>('overview');
 const [date,setDate]=useState(new Date().toISOString().slice(0,10)); const [attendance,setAttendance]=useState<Attendance[]>([]);
 const [lessons,setLessons]=useState<Lesson[]>([]); const [title,setTitle]=useState(''); const [content,setContent]=useState('');
 const [messages,setMessages]=useState<Msg[]>([]); const [message,setMessage]=useState(''); const [replyTo,setReplyTo]=useState<Msg|null>(null); const [file,setFile]=useState<File|null>(null); const [busy,setBusy]=useState(false); const inputRef=useRef<HTMLInputElement|null>(null);
 const allowedManager=isManager(session.role); const canEditContent=allowedManager||session.role==='servant'||session.role==='sector_secretary';
 useEffect(()=>{(async()=>{if(!classId){setRoom(null);return}try{
   const c=await supabase(`classes?select=id,sector_id,name,servant_id&id=eq.${encodeURIComponent(classId)}&limit=1`);
   const r=c?.[0] as ClassRoom|undefined; setRoom(r||null); if(!r)return;
   const all=await supabase(`profiles?select=id,full_name,username,role,sector_id,class_id,active,phone,birth_date,address,gender,stage,grade&role=eq.member&class_id=eq.${encodeURIComponent(classId)}&order=full_name.asc`);
   setMembers(all||[]);
 }catch{setRoom(null);setMembers([])}})()},[classId,refreshKey]);
 const access=!!room && (allowedManager || session.role==='sector_secretary'&&room.sector_id===session.sector_id || session.role==='servant'&&room.servant_id===session.id || session.role==='member'&&session.class_id===room.id);
 useEffect(()=>{if(!room||!access)return;(async()=>{try{
   const a=await supabase(`attendance?select=id,class_id,member_id,date,present,attendance_type,marked_by&class_id=eq.${encodeURIComponent(room.id)}&date=eq.${date}&attendance_type=eq.service`);setAttendance(a||[]);
   const l=await supabase(`lessons?select=id,sector_id,class_id,title,content,created_at&class_id=eq.${encodeURIComponent(room.id)}&order=created_at.desc`);setLessons(l||[]);
   const m=await supabase(`class_chat_messages?select=id,class_id,sender_id,text,created_at,reply_to,attachment_path,attachment_name,attachment_type,attachment_size,delivered_at,read_by&class_id=eq.${encodeURIComponent(room.id)}&order=created_at.asc&limit=200`);setMessages(m||[]);await Promise.all((m as Msg[]).filter(x=>x.sender_id!==session.id).map(x=>markChatSeen('class',x.id)));
 }catch{}})()},[room?.id,access,date,refreshKey]);
 async function mark(m:Profile,present:boolean){if(!room)return;try{const old=attendance.find(x=>x.member_id===m.id);if(old){await supabase(`attendance?id=eq.${old.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({present,marked_by:session.id})});setAttendance(attendance.map(x=>x.id===old.id?{...x,present,marked_by:session.id}:x))}else{const r=await supabase('attendance',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({class_id:room.id,member_id:m.id,date,present,attendance_type:'service',marked_by:session.id})});setAttendance([...attendance,...(r||[])]);}}catch(e:any){alert(e.message)}}
 async function addLesson(e:FormEvent){e.preventDefault();if(!room||!title.trim()||!content.trim())return;try{await supabase('lessons',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({sector_id:room.sector_id,class_id:room.id,title:title.trim(),content:content.trim()})});setTitle('');setContent('');const l=await supabase(`lessons?select=id,sector_id,class_id,title,content,created_at&class_id=eq.${encodeURIComponent(room.id)}&order=created_at.desc`);setLessons(l||[])}catch(e:any){alert(e.message)}}
 async function sendChat(e:FormEvent){e.preventDefault();if(!room||(!message.trim()&&!file))return;setBusy(true);try{let att:any={};if(file){const safe=file.name.replace(/[^\w\-.\u0600-\u06FF]+/g,'_');const path=`class/${room.id}/${session.id}/${crypto.randomUUID()}-${safe}`;const enc=path.split('/').map(encodeURIComponent).join('/');const token=localStorage.getItem('ss_access_token')||'';const res=await fetch(`${ENV_URL}/storage/v1/object/chat-media/${enc}`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});if(!res.ok)throw new Error('فشل رفع المرفق');att={attachment_path:path,attachment_name:file.name,attachment_type:file.type||'application/octet-stream',attachment_size:file.size}}await supabase('class_chat_messages',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({class_id:room.id,sender_id:session.id,text:message.trim(),reply_to:replyTo?.id||null,...att})});setMessage('');setFile(null);setReplyTo(null);if(inputRef.current)inputRef.current.value='';const m=await supabase(`class_chat_messages?select=id,class_id,sender_id,text,created_at,reply_to,attachment_path,attachment_name,attachment_type,attachment_size,delivered_at,read_by&class_id=eq.${encodeURIComponent(room.id)}&order=created_at.asc&limit=200`);setMessages(m||[]);await Promise.all((m as Msg[]).filter(x=>x.sender_id!==session.id).map(x=>markChatSeen('class',x.id)))}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 if(!room)return <><PageTitle title="مساحة الفصل"><button className="secondary-btn" onClick={onBack}><ChevronLeft/> العودة للفصول</button></PageTitle><div className="empty class-hub-empty">لم يتم اختيار فصل بعد.</div></>;
 if(!access)return <><PageTitle title="غير مسموح" sub="لا يمكنك الوصول إلى هذا الفصل"/><div className="empty class-hub-empty">هذا الفصل خارج نطاق صلاحيات حسابك.</div></>;
 const present=new Set(attendance.filter(a=>a.present).map(a=>a.member_id)); const pct=members.length?Math.round(present.size/members.length*100):0;
 const tabs:[typeof tab,string,any][]=[['overview','نظرة عامة',LayoutDashboard],['members','الأعضاء',Users],['attendance','الحضور',CalendarCheck],['content','المحتوى',BookOpen],['chat','الشات',MessageCircle],['reports','التقارير',Printer]];
 return <section className="class-hub">
  <PageTitle title={room.name} sub={`${sectors.find(s=>s.id===room.sector_id)?.name||''} · مساحة الفصل الكاملة`}><button className="secondary-btn" onClick={onBack}><ChevronLeft/> الفصول</button></PageTitle>
  <div className="class-hub-hero"><div><span>{sectors.find(s=>s.id===room.sector_id)?.emoji||'📚'}</span><div><h2>{room.name}</h2><p>{members.length} مخدوم · مساحة واحدة للأعضاء والحضور والمحتوى والشات والافتقاد والتقارير</p></div></div></div>
  <div className="class-hub-tabs">{tabs.map(([id,label,I])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}><I size={17}/>{label}</button>)}</div>
  {tab==='overview'&&<div className="class-hub-grid"><button onClick={()=>setTab('members')}><Users/><b>{members.length}</b><span>الأعضاء</span></button><button onClick={()=>setTab('attendance')}><CalendarCheck/><b>{pct}%</b><span>حضور اليوم</span></button><button onClick={()=>setTab('content')}><BookOpen/><b>{lessons.length}</b><span>محتوى الفصل</span></button><button onClick={()=>setTab('chat')}><MessageCircle/><b>شات</b><span>محادثة الفصل</span></button><button onClick={()=>setTab('reports')}><Printer/><b>تقارير</b><span>طباعة ومتابعة</span></button></div>}
  {tab==='members'&&<div className="table-card class-inner-card"><div className="class-inner-head"><h3>أعضاء الفصل</h3><span>{members.length} مخدوم</span></div><table><thead><tr><th>الاسم</th><th>الصف</th><th>الهاتف</th><th>تاريخ الميلاد</th><th>العنوان</th></tr></thead><tbody>{members.map(m=><tr key={m.id}><td><b>{m.full_name}</b></td><td>{m.grade||'—'}</td><td>{m.phone||'—'}</td><td>{m.birth_date?new Date(m.birth_date+'T00:00:00').toLocaleDateString('ar-EG'):'—'}</td><td>{m.address||'—'}</td></tr>)}</tbody></table></div>}
  {tab==='attendance'&&<div className="class-inner-card"><div className="class-inner-head"><div><h3>حضور الفصل</h3><span>{present.size}/{members.length} · {pct}%</span></div><label>التاريخ<input type="date" value={date} onChange={e=>setDate(e.target.value)}/></label></div><div className="class-attendance-list">{members.map(m=><div key={m.id} className="class-att-row"><div><b>{m.full_name}</b><small>{m.grade||''}</small></div><div><button className={present.has(m.id)?'attendance-fast present':'attendance-fast'} onClick={()=>mark(m,true)}>✓ حاضر</button><button className={!present.has(m.id)?'attendance-fast absent':'attendance-fast'} onClick={()=>mark(m,false)}>غياب</button></div></div>)}</div></div>}
  {tab==='content'&&<div className="class-content"><div className="class-inner-card">{canEditContent&&<form className="lesson-form class-lesson-form" onSubmit={addLesson}><input value={title} onChange={e=>setTitle(e.target.value)} placeholder="عنوان محتوى الفصل" required/><textarea value={content} onChange={e=>setContent(e.target.value)} placeholder="اكتب الدرس أو التأمل الخاص بالفصل..." required/><button className="primary"><BookOpen size={17}/> نشر في الفصل</button></form>}{lessons.map(l=><article className="lesson-card" key={l.id}><BookOpen size={20}/><div><h3>{l.title}</h3><p>{l.content}</p><small>{new Date(l.created_at).toLocaleDateString('ar-EG')}</small></div></article>)}{!lessons.length&&<div className="empty">لا يوجد محتوى منشور لهذا الفصل.</div>}</div></div>}
  {tab==='chat'&&<div className="chat-box class-chat-box"><div className="chat-head"><span>💬</span><div><b>شات {room.name}</b><small>أعضاء الفصل وخدامه · رسائل ومرفقات</small></div></div><div className="messages">{messages.map(m=><Message key={m.id} msg={m} own={m.sender_id===session.id} reply={m.reply_to?messages.find(x=>x.id===m.reply_to)||null:null} onReply={()=>setReplyTo(m)} onMention={()=>{}} formatSize={(n)=>n?`${Math.ceil(n/1024)} KB`:''}/>)}</div><form className="composer" onSubmit={sendChat}>{replyTo&&<div className="reply-preview"><Reply size={14}/>{replyTo.text||'رسالة'}<button type="button" onClick={()=>setReplyTo(null)}><X size={14}/></button></div>}<div className="composer-row"><button type="button" className="chat-tool" onClick={()=>inputRef.current?.click()} aria-label="إرفاق ملف"><Paperclip size={18}/></button><input ref={inputRef} type="file" hidden accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.zip,.rar" onChange={e=>setFile(e.target.files?.[0]||null)}/><button type="button" className="chat-tool" onClick={()=>setMessage(v=>(v?v+" ":"")+"@")} aria-label="منشن"><AtSign size={18}/></button><textarea className="chat-textarea" rows={1} value={message} onChange={e=>{setMessage(e.target.value);growChatTextarea(e.currentTarget)}} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.currentTarget.form?.requestSubmit()}}} placeholder="اكتب رسالة..."/><button className="chat-send" disabled={busy||(!message.trim()&&!file)}>{busy?'...':<Send size={17}/>}</button></div></form></div>}

  {tab==='reports'&&<div className="class-hub-grid"><button onClick={()=>window.print()}><Printer/><b>طباعة تقرير الفصل</b><span>أعضاء وحضور الفصل</span></button><button onClick={()=>setTab('attendance')}><CalendarCheck/><b>كشف الحضور</b><span>اختيار اليوم وطباعة الكشف</span></button><button onClick={()=>setTab('members')}><Users/><b>كشف المخدومين</b><span>بيانات أعضاء الفصل</span></button></div>}
 </section>
}

function Members({session,refresh,refreshKey}:{session:Profile;refresh:()=>void;refreshKey:number}){
 const [members,setMembers]=useState<Profile[]>([]); const [classes,setClasses]=useState<ClassRoom[]>([]); const [search,setSearch]=useState(''); const [modal,setModal]=useState(false); const [bulkModal,setBulkModal]=useState(false); const [qrMember,setQrMember]=useState<Profile|null>(null);
 useEffect(()=>{(async()=>{try{const [m,c]=await Promise.all([supabase('profiles?select=*&role=eq.member&order=full_name.asc'),supabase('classes?select=id,sector_id,name')]);setMembers(m||[]);setClasses(c||[])}catch{}})()},[refreshKey]);
 const scopedMembers=useMemo(()=>{
   if(isManager(session.role)) return members;
   if(session.role==='servant'){
     const ownClassIds=new Set(classes.filter(c=>c.sector_id===session.sector_id&&c.servant_id===session.id).map(c=>c.id));
     return members.filter(m=>ownClassIds.has(m.class_id||''));
   }
   return members.filter(m=>sectorMatches(m.sector_id,session.sector_id));
 },[members,classes,session.role,session.sector_id,session.id]);
 const visible=scopedMembers.filter(m=>[m.full_name,m.phone||''].some(v=>v.toLowerCase().includes(search.toLowerCase())));
 return <><PageTitle title="المخدومون" sub="بيانات المخدومين مع بطاقة حضور QR">{canManageMembers(session.role)&&<div className="page-actions"><button className="secondary-action" onClick={()=>setBulkModal(true)}><Upload/>استيراد مخدومين Excel</button><button className="primary" onClick={()=>setModal(true)}><UserPlus/>إنشاء حساب مخدوم</button></div>}</PageTitle><div className="table-card"><div className="table-search"><Search size={17}/><input placeholder="ابحث باسم المخدوم أو الهاتف..." value={search} onChange={e=>setSearch(e.target.value)}/></div><table><thead><tr><th>المخدوم</th><th>الصف</th><th>تاريخ الميلاد</th><th>الهاتف</th><th>القطاع</th><th>الفصل</th><th>الحضور</th><th>QR</th><th>الإجراء</th></tr></thead><tbody>{visible.map(m=><tr key={m.id}><td><b>{m.full_name}</b><small>{m.username}</small></td><td>{m.grade||'—'}</td><td>{m.birth_date?new Date(m.birth_date+'T00:00:00').toLocaleDateString('ar-EG'):'—'}</td><td>{m.phone?<a href={`tel:${m.phone}`}>{m.phone}</a>:'—'}</td><td>{sectors.find(s=>s.id===m.sector_id)?.name||'غير معين'}</td><td>{classes.find(c=>c.id===m.class_id)?.name||'غير معين'}</td><td><button className="promote" onClick={()=>{window.dispatchEvent(new CustomEvent('open-member-attendance',{detail:m.id}))}}><Percent size={15}/> النسبة</button></td><td><button className="icon-btn" onClick={()=>setQrMember(m)} aria-label="بطاقة QR"><QrCode size={18}/></button></td><td>{isManager(session.role)&&<button className="promote" onClick={()=>promote(m,classes,refresh)}>نقل للقطاع الأعلى <ArrowUpCircle/></button>}</td></tr>)}</tbody></table>{visible.length===0&&<div className="empty">لا توجد نتائج.</div>}</div>{modal&&<CreateMember session={session} classes={classes} onClose={()=>setModal(false)} onDone={()=>{setModal(false);refresh()}}/>}{bulkModal&&<BulkMemberImport session={session} classes={classes} sectors={sectors} onClose={()=>setBulkModal(false)} onDone={()=>{setBulkModal(false);refresh()}}/>}{qrMember&&<MemberQR member={qrMember} onClose={()=>setQrMember(null)}/>}</>
}
function MemberQR({member,onClose}:{member:Profile;onClose:()=>void}){const value=`khidma-member:${member.id}`;const src=`https://api.qrserver.com/v1/create-qr-code/?size=260x260&margin=12&data=${encodeURIComponent(value)}`;function print(){window.print()}return <Modal title="بطاقة حضور المخدوم" onClose={onClose}><div className="member-qr-card print-member-card"><div className="qr-brand">☦</div><h3>{member.full_name}</h3><p>{member.phone||'بدون هاتف'}</p><img src={src} alt="QR Code"/><small>يتم مسح هذا الكود بواسطة الخادم لتسجيل الحضور.</small><button className="primary full no-print" onClick={print}><Printer size={17}/> طباعة بطاقة الحضور</button></div></Modal>}
function CreateMember({session,classes,onClose,onDone}:{session:Profile;classes:ClassRoom[];onClose:()=>void;onDone:()=>void}){
 const visibleClasses=useMemo(()=>{if(isManager(session.role)) return classes;const sectorClasses=classes.filter(c=>c.sector_id===session.sector_id);return session.role==='servant'?sectorClasses.filter(c=>c.servant_id===session.id):sectorClasses;},[classes,session.role,session.sector_id,session.id]); const [name,setName]=useState(''); const [username,setUsername]=useState(''); const [password,setPassword]=useState(''); const [phone,setPhone]=useState(''); const [birthDate,setBirthDate]=useState(''); const [address,setAddress]=useState(''); const [gender,setGender]=useState<'male'|'female'>('male'); const [grade,setGrade]=useState(''); const [classId,setClassId]=useState(visibleClasses[0]?.id||''); const [busy,setBusy]=useState(false);
 useEffect(()=>{if(!visibleClasses.some(c=>c.id===classId))setClassId(visibleClasses[0]?.id||'')},[visibleClasses,classId]);
 async function submit(e:FormEvent){e.preventDefault();const c=visibleClasses.find(x=>x.id===classId);if(!c){alert(session.role==='servant'?'لا يوجد فصل مسند إليك في قطاعك. اطلب من أمين الخدام أو المسؤول إسناد فصل لك.':'اختر فصلًا صحيحًا.');return}setBusy(true);try{const r=await fetch('/api/create-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('ss_access_token')}`},body:JSON.stringify({full_name:name,username,password,role:'member',sector_id:c.sector_id,class_id:c.id,phone,birth_date:birthDate||null,address:address||null,gender,grade:grade||null,stage:c.sector_id==='baby'?'baby':c.sector_id.includes('prep')?'prep':c.sector_id.includes('secondary')?'secondary':c.sector_id==='youth'||c.sector_id.startsWith('youth_')?'youth':'primary'})});const raw=await r.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{d={error:raw||'استجابة غير صالحة من الخادم'}}if(!r.ok)throw new Error(d.error||'فشل إنشاء الحساب');onDone()}catch(e:any){alert(e.message)}finally{setBusy(false)}}
 return <Modal title="إنشاء حساب مخدوم" onClose={onClose}>{session.role==='servant'&&visibleClasses.length===0&&<div className="modal-help">لا يوجد حاليًا فصل مسند إليك. اطلب من أمين الخدام أو المسؤول إسناد فصل لك أولًا.</div>}<form onSubmit={submit}><label>اسم المخدوم<input value={name} onChange={e=>setName(e.target.value)} required/></label><label>تاريخ الميلاد<input type="date" value={birthDate} onChange={e=>setBirthDate(e.target.value)}/></label><label>النوع<select value={gender} onChange={e=>setGender(e.target.value as 'male'|'female')}><option value="male">بنين / ذكر</option><option value="female">بنات / أنثى</option></select></label><label>الصف الدراسي<select value={grade} onChange={e=>setGrade(e.target.value)}><option value="">اختر الصف</option>{GRADE_ORDER.map(g=><option key={g} value={g}>{g}</option>)}</select></label><label>رقم الهاتف<input type="tel" value={phone} onChange={e=>setPhone(e.target.value)} placeholder="01xxxxxxxxx"/></label><label>العنوان<input value={address} onChange={e=>setAddress(e.target.value)} placeholder="العنوان بالتفصيل"/></label><label>اسم المستخدم<input value={username} onChange={e=>setUsername(e.target.value)} required autoComplete="username"/></label><label>كلمة المرور المؤقتة<input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={6}/></label><label>الفصل<select value={classId} onChange={e=>setClassId(e.target.value)} required disabled={visibleClasses.length===0}><option value="">اختر الفصل</option>{visibleClasses.map(c=><option value={c.id} key={c.id}>{sectors.find(s=>s.id===c.sector_id)?.name} — {c.name}</option>)}</select></label><button className="primary full" disabled={busy||visibleClasses.length===0}><UserPlus/>{busy?'جاري الإنشاء...':'إنشاء الحساب'}</button></form></Modal>}

function Accounts({session,refresh,refreshKey}:{session:Profile;refresh:()=>void;refreshKey:number}){
 const [profiles,setProfiles]=useState<Profile[]>([]); const [classes,setClasses]=useState<ClassRoom[]>([]); const [modal,setModal]=useState(false); const [bulkModal,setBulkModal]=useState(false); const [transferModal,setTransferModal]=useState(false); const [passwordTarget,setPasswordTarget]=useState<Profile|null>(null);
 useEffect(()=>{(async()=>{try{const [rows,classRows]=await Promise.all([supabase('profiles?select=*&order=role.asc,full_name.asc'),supabase('classes?select=id,sector_id,name,servant_id&order=name.asc')]);const scoped=(rows||[]).filter((p:Profile)=>{
   if(session.role==='site_admin') return p.role!=='site_admin';
   if(session.role==='priest') return p.role!=='site_admin';
   if(session.role==='secretary') return ['sector_secretary','servant','member'].includes(p.role);
   if(session.role==='sector_secretary') return ['servant','member'].includes(p.role) && p.sector_id===session.sector_id;
   return false;
 });setProfiles(scoped);setClasses((classRows||[]) as ClassRoom[])}catch{setProfiles([]);setClasses([])}})()},[refreshKey,session.role,session.sector_id]);
 const servants=profiles.filter(p=>p.role==='servant'&&p.active);
 return <><PageTitle title="الحسابات وكلمات المرور" sub="إدارة الحسابات وتغيير كلمات المرور حسب الصلاحية">
   {canManageAccounts(session.role)&&<div className="page-actions"><button className="secondary-action" onClick={()=>setTransferModal(true)}><ArrowRightLeft/>نقل خادم بين القطاعات</button><button className="secondary-action" onClick={()=>setBulkModal(true)}><Upload/>استيراد Excel</button><button className="primary" onClick={()=>setModal(true)}><UserPlus/>إنشاء حساب</button></div>}
 </PageTitle>
 <div className="credentials-note"><b>تنبيه أمني:</b> كلمات المرور لا تظهر في النظام. استخدم زر <b>تغيير كلمة المرور</b> لتعيين كلمة مرور جديدة للحسابات المسموح بها.</div>
 <div className="permission-grid">{(['site_admin','priest','secretary','sector_secretary','servant','member'] as Role[]).map(r=><div key={r}><ShieldCheck/><h3>{roleName[r]}</h3><p>{r==='site_admin'?'إدارة النظام كاملة.':r==='priest'?'إدارة الكنيسة والقطاعات والقيادات.':r==='secretary'?'إدارة الفصول والخدام والمخدومين ونقل الخدام بين القطاعات.':r==='sector_secretary'?'إدارة قطاع واحد ومتابعة خدامه ومخدوميه وكلمات مرورهم.':r==='servant'?'إدارة مخدومي القطاع والفصول المسندة.':'حساب شخصي وشات القطاع.'}</p><strong>{profiles.filter(p=>p.role===r).length} حساب</strong></div>)}</div>
 <div className="table-card account-table"><table><thead><tr><th>الاسم</th><th>الحساب</th><th>الصلاحية</th><th>القطاع</th><th>الحالة</th><th>إجراء</th></tr></thead><tbody>{profiles.map(p=><tr key={p.id}><td>{p.full_name}</td><td>{p.username}</td><td><span className={`role ${p.role}`}>{roleName[p.role]}</span></td><td>{sectors.find(s=>s.id===p.sector_id)?.name||'كل القطاعات'}</td><td>{p.active?'نشط':'موقوف'}</td><td><div className="table-actions">{canChangePasswords(session.role)&&<button className="promote" onClick={()=>setPasswordTarget(p)}><ShieldCheck/>تغيير كلمة المرور</button>}{p.role==='servant'&&p.active&&canManageAccounts(session.role)&&<button className="promote" onClick={()=>setTransferModal(true)}><ArrowRightLeft/>نقل</button>}</div></td></tr>)}</tbody></table></div>
 {modal&&<CreateStaff session={session} onClose={()=>setModal(false)} onDone={()=>{setModal(false);refresh()}}/>}{bulkModal&&<BulkAccountImport session={session} classes={classes} sectors={sectors} onClose={()=>{setBulkModal(false);refresh()}}/>}{transferModal&&<TransferServant session={session} servants={servants} onClose={()=>setTransferModal(false)} onDone={()=>{setTransferModal(false);refresh()}}/>}{passwordTarget&&<ChangePasswordModal session={session} target={passwordTarget} onClose={()=>setPasswordTarget(null)} onDone={()=>setPasswordTarget(null)}/>}</>;
}
function BulkMemberImport({session,classes,sectors,onClose,onDone}:{session:Profile;classes:ClassRoom[];sectors:Sector[];onClose:()=>void;onDone:()=>void}){
 const [rows,setRows]=useState<any[]>([]); const [fileName,setFileName]=useState(''); const [busy,setBusy]=useState(false); const [results,setResults]=useState<{ok:number;failed:number;errors:string[]}|null>(null); const inputRef=useRef<HTMLInputElement|null>(null);
 const norm=(v:any)=>String(v??'').trim();
 const sectorMap:Record<string,string>={'بيبي':'baby','قطاع بيبي':'baby','ابتدائي':'primary','قطاع ابتدائي':'primary','إعدادي':'prep','إعدادي بنين':'prep_male','قطاع إعدادي بنين':'prep_male','إعدادي بنات':'prep_female','قطاع إعدادي بنات':'prep_female','ثانوي':'secondary','ثانوي بنين':'secondary_male','قطاع ثانوي بنين':'secondary_male','ثانوي بنات':'secondary_female','قطاع ثانوي بنات':'secondary_female','شباب':'youth','قطاع الشباب':'youth'};
 const stageMap:Record<string,string>={'بيبي':'baby','ابتدائي':'primary','إعدادي':'prep','ثانوي':'secondary','شباب':'youth'};
 const classByName=(name:string,sectorId:string)=>classes.find(c=>norm(c.name)===norm(name)&&c.sector_id===sectorId)||classes.find(c=>norm(c.name)===norm(name));
 const parseDate=(r:any)=>{const direct=norm(r.birth_date||r['تاريخ الميلاد']); if(direct && /^\d{4}-\d{2}-\d{2}$/.test(direct)) return direct; const d=Number(r.birth_day||r['يوم الميلاد']); const m=Number(r.birth_month||r['شهر الميلاد']); const y=Number(r.birth_year||r['سنة الميلاد']); if(Number.isInteger(d)&&Number.isInteger(m)&&Number.isInteger(y)&&d>=1&&d<=31&&m>=1&&m<=12&&y>=1900&&y<=new Date().getFullYear()) return `${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`; return null;};
 async function readFile(e:ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;setFileName(f.name);setResults(null);try{const data=await f.arrayBuffer();const wb=XLSX.read(data,{type:'array',cellDates:true});const sheet=wb.Sheets[wb.SheetNames[0]];const json=XLSX.utils.sheet_to_json(sheet,{defval:''});setRows(json as any[]);if(!json.length)alert('ملف Excel فارغ.');}catch(err:any){setRows([]);alert('تعذر قراءة ملف Excel: '+(err?.message||'تأكد أن الملف بصيغة xlsx أو xls.'));}}
 async function createAll(){if(!rows.length)return;setBusy(true);let ok=0,failed=0;const errors:string[]=[];try{for(let i=0;i<rows.length;i++){const r=rows[i];const full_name=norm(r.full_name||r.name||r['الاسم الكامل']||r['الاسم']);const username=norm(r.username||r['اسم المستخدم']);const password=norm(r.password||r['كلمة المرور']);const stageRaw=norm(r.stage||r['المرحلة']);const sectorRaw=norm(r.sector_id||r['القطاع']);const className=norm(r.class_name||r['class']||r['الفصل']);const stage=stageMap[stageRaw]||stageRaw;let sector_id=sectorMap[sectorRaw]||sectorRaw;const c=className?classByName(className,sector_id):undefined;if(!sector_id&&c)sector_id=c.sector_id; if(!full_name||!username||!password||!stage||!sector_id||!className){failed++;errors.push(`الصف ${i+2}: الاسم واسم المستخدم وكلمة المرور والمرحلة والقطاع والفصل مطلوبة.`);continue} const expectedStage=sector_id==='baby'?'baby':sector_id==='primary'?'primary':sector_id.includes('prep')?'prep':sector_id.includes('secondary')?'secondary':sector_id==='youth'?'youth':null; if(!expectedStage||expectedStage!==stage){failed++;errors.push(`الصف ${i+2} (${full_name}): المرحلة لا تتوافق مع القطاع.`);continue} if(!c||c.sector_id!==sector_id){failed++;errors.push(`الصف ${i+2} (${full_name}): الفصل \"${className}\" لا يتبع القطاع \"${sectorRaw}\".`);continue} const birth_date=parseDate(r); if((r['يوم الميلاد']||r['شهر الميلاد']||r['سنة الميلاد'])&&!birth_date){failed++;errors.push(`الصف ${i+2} (${full_name}): تاريخ الميلاد غير صحيح.`);continue} const body={full_name,username,password,role:'member',sector_id,class_id:c.id,phone:norm(r.phone||r['رقم الهاتف']||r['الهاتف'])||null,birth_date,address:norm(r.address||r['العنوان'])||null,gender:norm(r.gender||r['النوع'])||null,stage}; try{const res=await fetch('/api/create-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('ss_access_token')}`},body:JSON.stringify(body)});const raw=await res.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{d={error:raw||'استجابة غير صالحة'}}if(!res.ok)throw new Error(d.error||'فشل إنشاء الحساب');ok++;}catch(err:any){failed++;errors.push(`الصف ${i+2} (${full_name}): ${err.message||'فشل الإنشاء'}`)}}setResults({ok,failed,errors});if(ok>0)onDone();}finally{setBusy(false)}}
 return <Modal title="استيراد بيانات المخدومين من Excel" onClose={onClose}><div className="bulk-import"><div className="modal-help">القالب المعتمد: الاسم الكامل، اسم المستخدم، كلمة المرور، المرحلة، القطاع، الفصل، يوم الميلاد، شهر الميلاد، سنة الميلاد، النوع، رقم الهاتف، العنوان. لا يوجد بريد إلكتروني.</div><button type="button" className="secondary-action" onClick={()=>inputRef.current?.click()}><Upload/>اختيار ملف Excel</button><input ref={inputRef} type="file" hidden accept=".xlsx,.xls" onChange={readFile}/>{fileName&&<div className="bulk-file"><FileText size={16}/><span>{fileName}</span><b>{rows.length} صف</b></div>}{rows.length>0&&<div className="bulk-preview"><b>معاينة أول 5 صفوف</b>{rows.slice(0,5).map((r,i)=><div key={i}><span>{norm(r['الاسم الكامل']||r['الاسم'])||'بدون اسم'}</span><small>{norm(r['المرحلة'])} · {norm(r['القطاع'])} · {norm(r['الفصل'])}</small></div>)}</div>}{results&&<div className="bulk-results"><b>تم إنشاء {results.ok} مخدوم</b>{results.failed>0&&<><span>فشل {results.failed}</span><ul>{results.errors.slice(0,10).map((x,i)=><li key={i}>{x}</li>)}</ul></>}</div>}<button className="primary full" disabled={busy||!rows.length} onClick={createAll}>{busy?'جاري استيراد المخدومين...':<>استيراد {rows.length} مخدوم</>}</button></div></Modal>}

function BulkAccountImport({session,classes,sectors,onClose}:{session:Profile;classes:ClassRoom[];sectors:Sector[];onClose:()=>void}){
 const [rows,setRows]=useState<any[]>([]); const [fileName,setFileName]=useState(''); const [busy,setBusy]=useState(false); const [results,setResults]=useState<{ok:number;failed:number;errors:string[]}|null>(null); const inputRef=useRef<HTMLInputElement|null>(null);
 const normalize=(v:any)=>String(v??'').trim();
 const roleMap:Record<string,Role>={'مسؤول الموقع':'site_admin','أب الكنيسة':'priest','أمين الخدام':'secretary','أمين الخدمة':'secretary','أمين القطاع':'sector_secretary','خادم':'servant','مخدوم':'member'};
 const sectorMap:Record<string,string>={'بيبي':'baby','قطاع بيبي':'baby','ابتدائي':'primary','قطاع ابتدائي':'primary','إعدادي بنين':'prep_male','قطاع إعدادي بنين':'prep_male','إعدادي بنات':'prep_female','قطاع إعدادي بنات':'prep_female','ثانوي بنين':'secondary_male','قطاع ثانوي بنين':'secondary_male','ثانوي بنات':'secondary_female','قطاع ثانوي بنات':'secondary_female','شباب':'youth','قطاع الشباب':'youth'};
 const classByName=(name:string,sectorId:string)=>classes.find(c=>normalize(c.name)===normalize(name)&&(!sectorId||c.sector_id===sectorId))||classes.find(c=>normalize(c.name)===normalize(name));
 async function readFile(e:ChangeEvent<HTMLInputElement>){const f=e.target.files?.[0];if(!f)return;setFileName(f.name);setResults(null);try{const data=await f.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const ws=wb.Sheets[wb.SheetNames[0]];const json=XLSX.utils.sheet_to_json(ws,{defval:''});setRows(json as any[]);if(!json.length)alert('ملف Excel فارغ.');}catch(err:any){setRows([]);alert('تعذر قراءة ملف Excel: '+(err?.message||'تأكد أن الملف بصيغة xlsx أو xls.'));}}
 async function createAll(){if(!rows.length)return;setBusy(true);let ok=0,failed=0;const errors:string[]=[];try{for(let i=0;i<rows.length;i++){const r=rows[i];const full_name=normalize(r.full_name||r.name||r['الاسم']);const username=normalize(r.username||r['اسم المستخدم']);const email=normalize(r.email||r['البريد الإلكتروني']);const password=normalize(r.password||r['كلمة المرور']);const roleRaw=normalize(r.role||r['الصلاحية'])||'خادم';const role=(roleMap[roleRaw]||roleRaw) as Role;let sector_id=sectorMap[normalize(r.sector_id||r['القطاع'])]||normalize(r.sector_id||r['القطاع']);const className=normalize(r.class_name||r['class']||r['الفصل']);const c=className?classByName(className,sector_id):undefined;if(!sector_id&&c)sector_id=c.sector_id;if(!full_name||!username||!password){failed++;errors.push(`الصف ${i+2}: الاسم واسم المستخدم وكلمة المرور مطلوبة.`);continue}if(!['servant','sector_secretary','member','secretary'].includes(role)){failed++;errors.push(`الصف ${i+2}: الصلاحية ${role} غير مدعومة في الاستيراد.`);continue}if(role==='member'&&!c){failed++;errors.push(`الصف ${i+2}: لم يتم العثور على الفصل ${className||'المحدد'}.`);continue}const body={full_name,username,password,role,sector_id:sector_id||null,class_id:c?.id||null,phone:normalize(r.phone||r['الهاتف'])||null,birth_date:normalize(r.birth_date||r['تاريخ الميلاد'])||null,address:normalize(r.address||r['العنوان'])||null,gender:normalize(r.gender||r['النوع'])||null,stage:sector_id==='baby'?'baby':sector_id?.includes('prep')?'prep':sector_id?.includes('secondary')?'secondary':sector_id==='youth'||sector_id?.startsWith('youth_')?'youth':'primary'};try{const res=await fetch('/api/create-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('ss_access_token')}`},body:JSON.stringify(body)});const raw=await res.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{d={error:raw||'استجابة غير صالحة'}}if(!res.ok)throw new Error(d.error||'فشل إنشاء الحساب');ok++;}catch(err:any){failed++;errors.push(`الصف ${i+2} (${full_name}): ${err.message||'فشل الإنشاء'}`)}}setResults({ok,failed,errors});}finally{setBusy(false)}}
 return <Modal title="استيراد حسابات من Excel" onClose={onClose}><div className="bulk-import"><div className="modal-help">ارفع ملف Excel بالقالب العربي: الاسم، اسم المستخدم، كلمة المرور، نوع الحساب، القطاع، الفصل، الهاتف، تاريخ الميلاد، النوع، العنوان. لا تحتاج لإدخال بريد إلكتروني.</div><button type="button" className="secondary-action" onClick={()=>inputRef.current?.click()}><Upload/>اختيار ملف Excel</button><input ref={inputRef} type="file" hidden accept=".xlsx,.xls" onChange={readFile}/>{fileName&&<div className="bulk-file"><FileText size={16}/><span>{fileName}</span><b>{rows.length} صف</b></div>}{rows.length>0&&<div className="bulk-preview"><b>معاينة</b>{rows.slice(0,5).map((r,i)=><div key={i}><span>{normalize(r.full_name||r.name||r['الاسم'])||'بدون اسم'}</span><small>{normalize(r.role||r['الصلاحية'])||'خادم'} · {normalize(r.username||r['اسم المستخدم'])}</small></div>)}{rows.length>5&&<small>و {rows.length-5} حسابات أخرى...</small>}</div>}{results&&<div className="bulk-results"><b>تم إنشاء {results.ok} حساب</b>{results.failed>0&&<><span>فشل {results.failed}</span><ul>{results.errors.slice(0,8).map((x,i)=><li key={i}>{x}</li>)}</ul></>}</div>}<button className="primary full" disabled={busy||!rows.length} onClick={createAll}>{busy?'جاري إنشاء الحسابات...':<>إنشاء {rows.length} حساب دفعة واحدة</>}</button></div></Modal>}

function ChangePasswordModal({session,target,onClose,onDone}:{session:Profile;target:Profile;onClose:()=>void;onDone:()=>void}){
 const [password,setPassword]=useState(''); const [confirm,setConfirm]=useState(''); const [show,setShow]=useState(false); const [busy,setBusy]=useState(false);
 async function submit(e:FormEvent){e.preventDefault(); if(password.length<6){alert('كلمة المرور يجب أن تكون 6 أحرف على الأقل.');return} if(password!==confirm){alert('كلمتا المرور غير متطابقتين.');return} setBusy(true);try{const r=await fetch('/api/change-password',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('ss_access_token')}`},body:JSON.stringify({user_id:target.id,password})});const raw=await r.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{d={error:raw||'استجابة غير صالحة'}}if(!r.ok)throw new Error(d.error||'فشل تغيير كلمة المرور');alert('تم تغيير كلمة المرور بنجاح.');onDone()}catch(e:any){alert(e.message||'تعذر تغيير كلمة المرور')}finally{setBusy(false)}}
 return <Modal title="تغيير كلمة المرور" onClose={onClose}><div className="modal-help"><b>{target.full_name}</b><br/><small>{roleName[target.role]} · {target.username}</small></div><form onSubmit={submit}><label>كلمة المرور الجديدة<div className="password-field"><input type={show?'text':'password'} value={password} onChange={e=>setPassword(e.target.value)} minLength={6} required autoComplete="new-password"/><button type="button" onClick={()=>setShow(v=>!v)}>{show?<EyeOff size={16}/>:<Eye size={16}/>}</button></div></label><label>تأكيد كلمة المرور<input type={show?'text':'password'} value={confirm} onChange={e=>setConfirm(e.target.value)} minLength={6} required autoComplete="new-password"/></label><button className="primary full" disabled={busy}><Save/>{busy?'جاري التغيير...':'تغيير كلمة المرور'}</button></form></Modal>
}
function CreateStaff({session,onClose,onDone}:{session:Profile;onClose:()=>void;onDone:()=>void}){const allowed:Role[]=session.role==='site_admin'?['priest','secretary','sector_secretary','servant']:session.role==='priest'?['secretary','sector_secretary','servant']:['servant','sector_secretary'];const [name,setName]=useState('');const [username,setUsername]=useState('');const [password,setPassword]=useState('');const [role,setRole]=useState<Role>(allowed[0]);const [sector,setSector]=useState(session.sector_id||'');const [gender,setGender]=useState<'male'|'female'>('male');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();if(role==='servant'&&!sector){alert('اختر قطاع الخادم.');return}const targetSector=sector==='youth'?'youth':sector;setBusy(true);try{const r=await fetch('/api/create-user',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('ss_access_token')}`},body:JSON.stringify({full_name:name,username,password,role,sector_id:targetSector||null,gender,stage:sector==='baby'?'baby':sector.includes('prep')?'prep':sector.includes('secondary')?'secondary':sector==='youth'?'youth':'primary'})});const raw=await r.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{d={error:raw||'استجابة غير صالحة من الخادم'}}if(!r.ok)throw new Error(d.error||'فشل إنشاء الحساب');onDone()}catch(e:any){alert(e.message)}finally{setBusy(false)}}return <Modal title="إنشاء حساب" onClose={onClose}><form onSubmit={submit}><label>الاسم<input value={name} onChange={e=>setName(e.target.value)} required/></label><label>اسم المستخدم<input value={username} onChange={e=>setUsername(e.target.value)} required autoComplete="username"/></label><label>كلمة المرور المؤقتة<input type="password" value={password} onChange={e=>setPassword(e.target.value)} minLength={6} required/></label><label>الصلاحية<select value={role} onChange={e=>setRole(e.target.value as Role)}>{allowed.map(r=><option key={r} value={r}>{roleName[r]}</option>)}</select></label>{(role==='servant'||role==='sector_secretary')&&<label>النوع<select value={gender} onChange={e=>setGender(e.target.value as 'male'|'female')}><option value="male">بنين / ذكر</option><option value="female">بنات / أنثى</option></select></label>}{(role==='servant'||role==='sector_secretary')&&<label>القطاع<select value={sector} onChange={e=>setSector(e.target.value)}>{sectors.map(s=><option key={s.id} value={s.id}>{s.name}</option>)}</select></label>}<button className="primary full" disabled={busy}><Save/>{busy?'جاري الإنشاء...':'إنشاء الحساب'}</button></form></Modal>}

function Chat({session,selected,setSelected,refreshKey}:{session:Profile;selected:string;setSelected:(s:string)=>void;refreshKey:number}){
 const allowed=scopeSectors(session); const safeSelected=allowed.some(s=>s.id===selected)?selected:(allowed[0]?.id||'');
 const sector=sectors.find(s=>s.id===safeSelected); const [messages,setMessages]=useState<Msg[]>([]); const [text,setText]=useState(''); const [loading,setLoading]=useState(false); const [replyTo,setReplyTo]=useState<Msg|null>(null); const [file,setFile]=useState<File|null>(null); const [recording,setRecording]=useState(false); const recorderRef=useRef<MediaRecorder|null>(null); const streamRef=useRef<MediaStream|null>(null); const inputRef=useRef<HTMLInputElement|null>(null);
 useEffect(()=>{if(safeSelected&&safeSelected!==selected)setSelected(safeSelected)},[safeSelected,selected,setSelected]);
 async function signAttachment(item:Msg){if(!item.attachment_path)return item;try{const token=localStorage.getItem('ss_access_token')||'';const encoded=item.attachment_path.split('/').map(encodeURIComponent).join('/');const r=await fetch(`${ENV_URL}/storage/v1/object/sign/chat-media/${encoded}`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:3600})});const raw=await r.text();const d=raw?JSON.parse(raw):{};const u=d.signedURL||d.signedUrl||'';return {...item,attachment_signed_url:u?(u.startsWith('http')?u:`${ENV_URL}/storage/v1${u}`):''};}catch{return item}}
 async function load(){if(!safeSelected)return;try{const m=await supabase(`sector_messages?select=id,sector_id,sender_id,text,created_at,reply_to,attachment_path,attachment_name,attachment_type,attachment_size,delivered_at,read_by&sector_id=eq.${encodeURIComponent(safeSelected)}&order=created_at.asc`);const signed=await Promise.all((m||[]).map(signAttachment));setMessages(signed||[]);await Promise.all((signed as Msg[]).filter(x=>x.sender_id!==session.id).map(x=>markChatSeen('sector',x.id)))}catch(err:any){if(messages.length===0)console.error(err)}}
 useEffect(()=>{let mounted=true;const run=async()=>{if(!mounted)return;await load()};run();const id=window.setInterval(run,3000);return()=>{mounted=false;window.clearInterval(id)}},[safeSelected,refreshKey]);
 function pickFile(f:File|null){if(!f)return; if(f.size>50*1024*1024){alert('الحد الأقصى للملف 50MB.');return} setFile(f)}
 async function toggleRecording(){if(recording){recorderRef.current?.stop();return} if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){alert('تسجيل الصوت غير مدعوم في هذا المتصفح. استخدم Chrome أو Safari حديث.');return} try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});streamRef.current=stream;const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x))||'';const rec=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const chunks:BlobPart[]=[];rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=()=>{const type=rec.mimeType||'audio/webm';const ext=type.includes('mp4')?'m4a':'webm';setFile(new File([new Blob(chunks,{type})],`voice-${Date.now()}.${ext}`,{type}));setRecording(false);stream.getTracks().forEach(t=>t.stop());streamRef.current=null};recorderRef.current=rec;rec.start();setRecording(true)}catch{alert('تعذر الوصول إلى الميكروفون. اسمح للموقع باستخدام الميكروفون ثم حاول مرة أخرى.')}}
 async function send(e:FormEvent){e.preventDefault();const value=text.trim();if((!value&&!file)||!safeSelected)return;setLoading(true);try{let attachment:any={};if(file){const safeName=file.name.replace(/[^\w\-.\u0600-\u06FF]+/g,'_');const path=`${safeSelected}/${session.id}/${crypto.randomUUID()}-${safeName}`;const encoded=path.split('/').map(encodeURIComponent).join('/');const token=localStorage.getItem('ss_access_token')||'';const res=await fetch(`${ENV_URL}/storage/v1/object/chat-media/${encoded}`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});const raw=await res.text();let d:any={};try{d=raw?JSON.parse(raw):{}}catch{}if(!res.ok)throw new Error(d?.message||d?.error||raw||'فشل رفع الملف');attachment={attachment_path:path,attachment_name:file.name,attachment_type:file.type||'application/octet-stream',attachment_size:file.size}}
 const created=await supabase('sector_messages',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({sector_id:safeSelected,sender_id:session.id,text:value||'',reply_to:replyTo?.id||null,...attachment})});
 setText('');setFile(null);setReplyTo(null);if(inputRef.current)inputRef.current.value='';const fresh=await supabase(`sector_messages?select=id,sector_id,sender_id,text,created_at,reply_to,attachment_path,attachment_name,attachment_type,attachment_size,delivered_at,read_by&sector_id=eq.${encodeURIComponent(safeSelected)}&order=created_at.asc`);const signedFresh=await Promise.all((fresh||[]).map(signAttachment));setMessages(signedFresh);await Promise.all((signedFresh as Msg[]).filter(x=>x.sender_id!==session.id).map(x=>markChatSeen('sector',x.id)));void created;
 }catch(e:any){alert('تعذر إرسال الرسالة: '+e.message)}finally{setLoading(false)}}
 function mention(name:string){setText(v=>(v?`${v} `:'')+`@${name} `);setTimeout(()=>inputRef.current?.focus(),0)}
 const formatSize=(n?:number|null)=>!n?'':n<1024*1024?`${Math.ceil(n/1024)} KB`:`${(n/1024/1024).toFixed(1)} MB`;
 return <><PageTitle title="شات القطاعات" sub="رسائل وملفات القطاع مع الرد والمنشن"><span className="live"><i/> مباشر</span></PageTitle><div className="chat-layout"><div className="chat-sectors">{allowed.map(s=><button className={safeSelected===s.id?'active':''} key={s.id} onClick={()=>setSelected(s.id)}><span>{s.emoji}</span>{s.name.replace('قطاع ','')}</button>)}</div><div className="chat-box"><div className="chat-head"><span>{sector?.emoji}</span><div><b>{sector?.name||'القطاع'}</b><small>المحادثة الجماعية للقطاع · صور وفيديوهات وملفات</small></div></div><div className="messages">{messages.map(m=><Message key={m.id} msg={m} own={m.sender_id===session.id} reply={m.reply_to?messages.find(x=>x.id===m.reply_to)||null:null} onReply={()=>setReplyTo(m)} onMention={mention} formatSize={formatSize}/>)}{messages.length===0&&<div className="empty">لا توجد رسائل بعد. ابدأ المحادثة.</div>}</div><form className="composer" onSubmit={send}>{replyTo&&<div className="reply-preview"><div><Reply size={15}/><b>رد على رسالة</b><span>{replyTo.text||replyTo.attachment_name||'ملف'}</span></div><button type="button" onClick={()=>setReplyTo(null)} aria-label="إلغاء الرد"><X size={16}/></button></div>}{file&&<div className="attachment-preview"><Paperclip size={15}/><span>{file.name}</span><small>{formatSize(file.size)}</small><button type="button" onClick={()=>{setFile(null);if(inputRef.current)inputRef.current.value=''}}><X size={15}/></button></div>}<div className="composer-row"><button type="button" className={`chat-tool ${recording?'recording':''}`} onClick={toggleRecording} aria-label={recording?'إيقاف التسجيل':'تسجيل صوت'}>{recording?<Square size={18}/>:<Mic size={19}/>}</button><button type="button" className="chat-tool" onClick={()=>inputRef.current?.click()} aria-label="إرفاق ملف"><Paperclip size={19}/></button><input ref={inputRef} type="file" hidden accept="image/*,video/*,.pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.zip,.rar" onChange={e=>pickFile(e.target.files?.[0]||null)}/><button type="button" className="chat-tool" onClick={()=>{const name=prompt('اكتب اسم الشخص أو اختره من الرسائل:');if(name)mention(name)}} aria-label="منشن"><AtSign size={19}/></button><textarea className="chat-textarea" rows={1} value={text} onChange={e=>{setText(e.target.value);growChatTextarea(e.currentTarget)}} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.currentTarget.form?.requestSubmit()}}} placeholder="اكتب رسالة... استخدم @ للمنشن"/><button className="chat-send" disabled={loading||(!text.trim()&&!file)}>{loading?'...':<Send size={18}/>}</button></div></form></div></div></>
}
function Message({msg,own,reply,onReply,onMention,formatSize}:{msg:Msg;own:boolean;reply:Msg|null;onReply:()=>void;onMention:(name:string)=>void;formatSize:(n?:number|null)=>string}){
 const [name,setName]=useState(own?'أنت':'مستخدم'); const [avatar,setAvatar]=useState<string|null>(msg.avatar_url||null);
 useEffect(()=>{let active=true;(async()=>{try{const p=await supabase('profiles?select=full_name,avatar_url&id=eq.'+encodeURIComponent(msg.sender_id)+'&limit=1');if(active&&p?.[0]){setName(p[0].full_name);setAvatar(p[0].avatar_url||null)}}catch{}})();return()=>{active=false}},[msg.sender_id]);
 const isImage=!!msg.attachment_type?.startsWith('image/'); const isVideo=!!msg.attachment_type?.startsWith('video/'); const isAudio=!!msg.attachment_type?.startsWith('audio/');
 const read=!!(msg.read_by||[]).length; const delivered=!!msg.delivered_at;
 return <div className={'message '+(own?'own':'')}>{!own&&<div className="message-avatar">{avatar?<img src={avatar} alt=""/>:name.slice(0,1)}</div>}<div className="message-card">{!own&&<b className="message-sender">{name}</b>}{reply&&<div className="quoted-message"><Reply size={13}/><span>{reply.text||reply.attachment_name||'مرفق'}</span></div>}{msg.text&&<p>{msg.text.split(/(@[^\s@]+)/g).map((part,i)=>part.startsWith('@')?<mark key={i}>{part}</mark>:part)}</p>}{msg.attachment_signed_url&&<div className="chat-attachment">{isImage?<img src={msg.attachment_signed_url} alt={msg.attachment_name||'صورة'}/>:isVideo?<video src={msg.attachment_signed_url} controls/>:isAudio?<div className="voice-message"><Mic size={18}/><audio src={msg.attachment_signed_url} controls preload="metadata"/></div>:<a href={msg.attachment_signed_url} target="_blank" rel="noreferrer" className="file-attachment"><FileText size={22}/><span><b>{msg.attachment_name||'ملف'}</b><small>{formatSize(msg.attachment_size)}</small></span><Download size={17}/></a>}</div>}<div className="message-meta"><span>{new Date(msg.created_at).toLocaleTimeString('ar-EG',{hour:'2-digit',minute:'2-digit'})}</span>{own&&<span className={'message-status '+(read?'read':'')} aria-label={read?'تمت القراءة':delivered?'تم التسليم':'تم الإرسال'}>{read?'✓✓':delivered?'✓✓':'✓'}</span>}</div><div className="message-actions"><button type="button" onClick={onReply}><Reply size={13}/> رد</button><button type="button" onClick={()=>onMention(name)}><AtSign size={13}/> منشن</button></div></div></div>
}
