 const isAdmin=session.role==='site_admin'||session.role==='priest'||session.role==='secretary';
 const stageMap:any={prep:{label:'إعدادي',sector:'prep',icon:'📚'},secondary:{label:'ثانوي',sector:'secondary',icon:'🎓'},youth:{label:'شباب',sector:'youth',icon:'🔥'}};
