 async function sign(item:Msg){if(!item.attachment_path)return item;try{const token=localStorage.getItem('ss_access_token')||'';const encoded=item.attachment_path.split('/').map(encodeURIComponent).join('/');const r=await fetch(`${ENV_URL}/storage/v1/object/sign/staff-chat-media/${encoded}`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({expiresIn:3600})});const d=await r.json();const u=d.signedURL||d.signedUrl||'';return {...item,attachment_signed_url:u?(u.startsWith('http')?u:`${ENV_URL}/storage/v1${u}`):''}}catch{return item}}
 async function load(){if(!room)return;try{const rows=await supabase(`staff_chat_messages?select=id,room,sender_id,text,created_at,reply_to,attachment_path,attachment_name,attachment_type,attachment_size,delivered_at,read_by&room=eq.${encodeURIComponent(room)}&order=created_at.asc`);setMessages(await Promise.all((rows||[]).map(sign)))}catch{}}
