 async function send(e:FormEvent){e.preventDefault();if(!room||(!text.trim()&&!file))return;setBusy(true);try{let attachment:any={};if(file){const safe=file.name.replace(/[^\w\-.\u0600-\u06FF]+/g,'_');const path=`groups/${room}/${session.id}/${crypto.randomUUID()}-${safe}`;const token=localStorage.getItem('ss_access_token')||'';const r=await fetch(`${ENV_URL}/storage/v1/object/staff-chat-media/${path.split('/').map(encodeURIComponent).join('/')}`,{method:'POST',headers:{apikey:ENV_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type||'application/octet-stream','x-upsert':'false'},body:file});if(!r.ok)throw new Error('فشل رفع المرفق');attachment={attachment_path:path,attachment_name:file.name,attachment_type:file.type||'application/octet-stream',attachment_size:file.size}}
 await supabase('staff_chat_messages',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({room,sender_id:session.id,text:text.trim(),reply_to:replyTo?.id||null,...attachment})});setText('');setFile(null);setReplyTo(null);if(inputRef.current)inputRef.current.value='';await load()}catch(e:any){alert(e.message||'تعذر إرسال الرسالة')}finally{setBusy(false)}}
